using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.ENC.Preguntas;using GraphApi.Services.ENC.Preguntas;namespace GraphApi.Controllers.ENC.Preguntas{    /// <summary>    /// Gestión de Preguntas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("ENC/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Preguntas")]    public class PreguntasController : Controller    {        private readonly IPreguntasService _objService;        public PreguntasController(IPreguntasService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Preguntas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="preguntaID">PreguntaID</param>        /// <param name="encuestaID">EncuestaID</param>        /// <param name="texto">Texto</param>        /// <param name="tipoPreguntaID">TipoPreguntaID</param>        /// <param name="orden">Orden</param>        /// <param name="requerida">Requerida</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Preguntas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Preguntas",            Description = "Devuelve Preguntas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadPreguntas>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadPreguntas>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? preguntaID,            [FromQuery] int? encuestaID,            [FromQuery] string? texto,            [FromQuery] int? tipoPreguntaID,            [FromQuery] int? orden,            [FromQuery] bool? requerida,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetPreguntasDynamic(                preguntaID,                 encuestaID,                 texto,                 tipoPreguntaID,                 orden,                 requerida,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Pregunta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Pregunta a crear.</param>        /// <returns>El Pregunta recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Preguntas",            Description = "Inserta un nuevo Pregunta en la base de datos."        )]        [ProducesResponseType(typeof(clReadPreguntas), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadPreguntas>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreatePreguntas objInput)        {            var vCreated = await _objService.CreatePreguntas(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Pregunta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Pregunta.</param>        /// <returns>El Pregunta actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Preguntas",            Description = "Actualiza uno o varios campos de Pregunta existente."        )]        [ProducesResponseType(typeof(clReadPreguntas), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadPreguntas>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdatePreguntas objInput)        {            var vUpdated = await _objService.UpdatePreguntas(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Pregunta por su ID.        /// </summary>        [HttpDelete("{nPreguntasID:int}")]        [SwaggerOperation(            Summary = "Eliminar Pregunta",            Description = "Borra un Pregunta si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nPreguntasID)        {            var success = await _objService.DeletePreguntas(nPreguntasID);            return success ? NoContent() : NotFound();        }    }}